  for mode,items in cases.items():
   for case in items:
    cmd=f'bash {STAGE}/run.sh {runtime} {variant} {mode} {case}';record={'runtime':runtime,'variant':variant,'mode':mode,'case':case,'command':cmd,**remote([cmd])};record['stderr_sha256']=sha(record['stderr'].encode());record['lints']=[]
    try:
     b=parse_record(record,manifest)
     if b:
      for path,data in decode_outputs(b).items():
       if path.endswith('.php'):
        for lint_runtime in ['74','83']:
         lint=remote([f'bash {STAGE}/run.sh {lint_runtime} {variant} lint stdin'],data);require(type(lint['exit']) is int and lint['exit'] in [0,255],'Unknown lint status');record['lints'].append({'path':path,'runtime':lint_runtime,**lint})
