 report={'schema':1,'status':'OBSERVED_PENDING_REVIEWED_CONTRACT' if not failures else 'FAILED_OBSERVATION_VALIDATION','runtime_acceptance':False,'generated_syntax_acceptance':False,'application_acceptance':False,'input_pins':{str(MANIFEST):sha(MANIFEST.read_bytes()),str(CASES):sha(CASES.read_bytes())},'harness_sha256':{n:sha((HERE/n).read_bytes()) for n in HARNESS},'identity_before':before,'identity_after':after,'records':records,'failures':failures,'limitations':['Exact reviewed diagnostics/native-stderr and generated-output goldens remain required; no row with DEBUGfalse lint failure is waived.']}
 a.output.write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'status':report['status'],'rows':len(records),'failures':len(failures)}));return 2
if __name__=='__main__':sys.exit(main())

